starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "key_name" {
  description = "Input variable key_name."
  type        = string
  default     = "app-key"
}

variable "public_key" {
  description = "Input variable public_key."
  type        = string
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_key_pair" "this" {
  # TODO - Complete the aws_key_pair resource.
  # Add the arguments and nested blocks required for aws_key_pair.
}
